struct ProviderSeed {
    id: &'static str,
    name: &'static str,
    description: &'static str,
    icon_key: Option<&'static str>,
    protocol: &'static str,
    base_url: Option<&'static str>,
    headers: &'static [(&'static str, &'static str)],
}

impl From<&ProviderSeed> for Value {
    fn from(seed: &ProviderSeed) -> Self {
        json!({
            "id": seed.id, "name": seed.name, "description": seed.description,
            "icon_key": seed.icon_key, "protocol": seed.protocol, "base_url": seed.base_url,
            "headers": seed.headers.iter().map(|(key, value)| ((*key).to_owned(), json!(value))).collect::<serde_json::Map<_, _>>(),
        })
    }
}

struct ModelSeed {
    provider_template_id: &'static str,
    id: &'static str,
    name: &'static str,
    description: &'static str,
    protocols: &'static [&'static str],
    paths: &'static [(&'static str, &'static str)],
    capabilities: &'static [&'static str],
    max_context_tokens: Option<u32>,
    effort_mapping: &'static [(&'static str, &'static str)],
    input_price: Option<&'static str>,
    output_price: Option<&'static str>,
    cached_price: Option<&'static str>,
}

impl From<&ModelSeed> for Value {
    fn from(seed: &ModelSeed) -> Self {
        json!({
            "provider_template_id": seed.provider_template_id, "id": seed.id,
            "name": seed.name, "description": seed.description, "protocols": seed.protocols,
            "paths": seed.paths.iter().map(|(key, value)| ((*key).to_owned(), json!(value))).collect::<serde_json::Map<_, _>>(),
            "capabilities": seed.capabilities, "max_context_tokens": seed.max_context_tokens,
            "effort_mapping": seed.effort_mapping.iter().map(|(key, value)| ((*key).to_owned(), json!(value))).collect::<serde_json::Map<_, _>>(),
            "input_price": seed.input_price, "output_price": seed.output_price, "cached_price": seed.cached_price,
        })
    }
}

